using Microsoft.Azure.Cosmos;

public class CosmosMemoryStore
{
    private readonly Container _container;

    public CosmosMemoryStore(CosmosClient cosmosClient)
    {
        _container = cosmosClient.GetContainer("EnterpriseDb", "UserMemories");
    }

    public async Task<List<MemoryRecord>> SearchSimilarMemoriesAsync(
        string userId,
        float[] queryEmbedding,
        int limit = 5,
        CancellationToken ct = default)
    {
        // Cosmos DB SQL VectorDistance function
        var queryDef = new QueryDefinition(
            "SELECT TOP @limit c.id, c.text, c.category, VectorDistance(c.embedding, @vector) AS similarityScore " +
            "FROM c " +
            "WHERE c.userId = @userId " +
            "ORDER BY VectorDistance(c.embedding, @vector)")
            .WithParameter("@limit", limit)
            .WithParameter("@userId", userId)
            .WithParameter("@vector", queryEmbedding);

        var options = new QueryRequestOptions
        {
            PartitionKey = new PartitionKey(userId)
        };

        using var feedIterator = _container.GetItemQueryIterator<MemoryRecord>(queryDef, requestOptions: options);
        var results = new List<MemoryRecord>();

        while (feedIterator.HasMoreResults)
        {
            var response = await feedIterator.ReadNextAsync(ct);
            results.AddRange(response);
        }

        return results;
    }
}

public record MemoryRecord(string Id, string Text, string Category, double SimilarityScore);
